from typing import Dict, List, Sequence, Tuple

from routekit.parse_edge import parse_edge


def graph_diff(old_lines: Sequence[str], new_lines: Sequence[str]) -> Dict[str, List[Tuple[str, str, int]]]:
    def norm(a: str, b: str) -> Tuple[str, str]:
        return (a, b) if a <= b else (b, a)

    old_roads: Dict[Tuple[str, str], int] = {}
    for line in old_lines:
        f, t, km = parse_edge(line)
        old_roads[norm(f, t)] = km

    new_roads: Dict[Tuple[str, str], int] = {}
    for line in new_lines:
        f, t, km = parse_edge(line)
        new_roads[norm(f, t)] = km

    old_keys = set(old_roads.keys())
    new_keys = set(new_roads.keys())

    added = sorted([(k[0], k[1], new_roads[k]) for k in new_keys - old_keys])
    removed = sorted([(k[0], k[1], old_roads[k]) for k in old_keys - new_keys])
    changed = sorted([(k[0], k[1], new_roads[k]) for k in old_keys & new_keys if old_roads[k] != new_roads[k]])

    return {"added": added, "removed": removed, "changed": changed}"}}, "messages": []}

